 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { Link } from 'react-router-dom'
import { 
  Bell, 
  Heart, 
  MessageCircle, 
  UserPlus, 
  Reply, 
  Building2, 
  Check, 
  Calendar,
  User,
  ArrowRight
} from 'lucide-react'

export default function Notifications() {
    const { user } = useAuth()
    const [notifications, setNotifications] = useState([])
    const [loading, setLoading] = useState(true)
    const [unreadCount, setUnreadCount] = useState(0)

    useEffect(() => {
        if (user) {
            loadNotifications()
            
            // Subscribe to new notifications
            const subscription = supabase
                .channel('notifications')
                .on(
                    'postgres_changes',
                    {
                        event: 'INSERT',
                        schema: 'public',
                        table: 'notifications',
                        filter: `user_id=eq.${user.id}`
                    },
                    (payload) => {
                        console.log('New notification:', payload.new)
                        setNotifications(prev => [payload.new, ...prev])
                        setUnreadCount(prev => prev + 1)
                    }
                )
                .subscribe()

            return () => {
                subscription.unsubscribe()
            }
        }
    }, [user])

    const loadNotifications = async () => {
        if (!user) return
        
        setLoading(true)
        try {
            console.log('Loading notifications for user:', user.id)
            
            // First, check if there are any notifications at all
            const { count, error: countError } = await supabase
                .from('notifications')
                .select('*', { count: 'exact', head: true })
                .eq('user_id', user.id)
            
            if (countError) {
                console.error('Count error:', countError)
            }
            console.log('Total notifications count:', count)

            // Get notifications with profile data
            const { data, error } = await supabase
                .from('notifications')
                .select(`
                    *,
                    from_user:from_user_id (id, username, full_name, avatar_url),
                    post:post_id (id, text),
                    comment:comment_id (id, text, post_id)
                `)
                .eq('user_id', user.id)
                .order('created_at', { ascending: false })
                .limit(50)

            if (error) {
                console.error('Query error:', error)
                throw error
            }

            console.log('Notifications data:', data)
            setNotifications(data || [])
            setUnreadCount(data?.filter(n => !n.read).length || 0)
        } catch (error) {
            console.error('Error loading notifications:', error)
            setNotifications([])
            setUnreadCount(0)
        } finally {
            setLoading(false)
        }
    }

    const markAsRead = async (notificationId) => {
        try {
            await supabase
                .from('notifications')
                .update({ read: true })
                .eq('id', notificationId)
            
            setNotifications(prev => 
                prev.map(n => 
                    n.id === notificationId ? { ...n, read: true } : n
                )
            )
            setUnreadCount(prev => Math.max(0, prev - 1))
        } catch (error) {
            console.error('Error marking notification as read:', error)
        }
    }

    const markAllAsRead = async () => {
        try {
            await supabase
                .from('notifications')
                .update({ read: true })
                .eq('user_id', user?.id)
                .eq('read', false)
            
            setNotifications(prev => 
                prev.map(n => ({ ...n, read: true }))
            )
            setUnreadCount(0)
        } catch (error) {
            console.error('Error marking all as read:', error)
        }
    }

    const getNotificationIcon = (type) => {
        switch(type) {
            case 'like': return <Heart size={18} className="text-red-500" />
            case 'comment': return <MessageCircle size={18} className="text-blue-500" />
            case 'follow': return <UserPlus size={18} className="text-green-500" />
            case 'reply': return <Reply size={18} className="text-purple-500" />
            case 'join': return <Building2 size={18} className="text-orange-500" />
            default: return <Bell size={18} className="text-gray-500" />
        }
    }

    const getNotificationLink = (notification) => {
        if (notification.type === 'follow') {
            return `/profile/${notification.from_user_id}`
        }
        if (notification.type === 'like' || notification.type === 'comment' || notification.type === 'reply') {
            if (notification.post_id) {
                return `/feed?highlight=${notification.post_id}`
            }
            if (notification.comment_id && notification.comment) {
                return `/feed?highlight=${notification.comment.post_id}&comment=${notification.comment_id}`
            }
            return '/feed'
        }
        if (notification.type === 'join') {
            return `/community/${notification.community_id}`
        }
        return '#'
    }

    const getNotificationMessage = (notification) => {
        const fromName = notification.from_user?.full_name || notification.from_user?.username || 'Someone'
        
        if (notification.type === 'like') {
            return `${fromName} liked your post`
        }
        if (notification.type === 'comment') {
            const commentText = notification.comment?.text?.substring(0, 50) || ''
            return `${fromName} commented: "${commentText}${commentText.length >= 50 ? '...' : ''}"`
        }
        if (notification.type === 'reply') {
            const replyText = notification.comment?.text?.substring(0, 50) || ''
            return `${fromName} replied to your comment: "${replyText}${replyText.length >= 50 ? '...' : ''}"`
        }
        if (notification.type === 'follow') {
            return `${fromName} started following you`
        }
        if (notification.type === 'join') {
            return `${fromName} joined your community`
        }
        return notification.message || `${fromName} interacted with you`
    }

    if (!user) {
        return (
            <div className="text-center py-12">
                <Bell className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500">Please sign in to view notifications</p>
            </div>
        )
    }

    return (
        <div className="max-w-3xl mx-auto px-4 py-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                        <Bell size={24} /> Notifications
                    </h1>
                    <p className="text-gray-400 text-sm">Stay updated with what's happening</p>
                </div>
                {unreadCount > 0 && (
                    <button
                        onClick={markAllAsRead}
                        className="px-4 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-900 transition text-sm flex items-center gap-1"
                    >
                        <Check size={16} /> Mark all as read ({unreadCount})
                    </button>
                )}
            </div>

            {loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-400">Loading notifications...</div>
                </div>
            ) : notifications.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-sm border border-gray-100">
                    <Bell className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                    <p className="text-gray-400">No notifications yet</p>
                    <p className="text-sm text-gray-300">When someone interacts with your posts, you'll see it here</p>
                    <button 
                        onClick={loadNotifications}
                        className="mt-4 text-sm text-gray-500 hover:text-gray-700 underline"
                    >
                        Refresh notifications
                    </button>
                </div>
            ) : (
                <div className="space-y-2">
                    {notifications.map((notification) => {
                        const link = getNotificationLink(notification)
                        const message = getNotificationMessage(notification)
                        const icon = getNotificationIcon(notification.type)
                        
                        return (
                            <Link
                                key={notification.id}
                                to={link}
                                onClick={() => markAsRead(notification.id)}
                                className={`block p-4 rounded-xl transition ${
                                    notification.read
                                        ? 'bg-white hover:bg-gray-50'
                                        : 'bg-gray-50 hover:bg-gray-100 border-l-4 border-gray-800'
                                }`}
                            >
                                <div className="flex items-start gap-4">
                                    <div className="mt-1 flex-shrink-0">
                                        {icon}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 flex-wrap">
                                            <span className="font-semibold text-gray-800">
                                                {notification.from_user?.full_name || notification.from_user?.username || 'Someone'}
                                            </span>
                                            <span className="text-gray-600 break-words">
                                                {message}
                                            </span>
                                        </div>
                                        <div className="flex items-center gap-2 mt-1 text-xs text-gray-400">
                                            <Calendar size={12} />
                                            <span>
                                                {new Date(notification.created_at).toLocaleDateString()} at {new Date(notification.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                            </span>
                                            {notification.read && (
                                                <span className="text-gray-300">• Read</span>
                                            )}
                                            {!notification.read && (
                                                <span className="text-green-600">• New</span>
                                            )}
                                        </div>
                                        {notification.post && notification.type !== 'follow' && (
                                            <div className="mt-2 text-xs text-gray-400 bg-gray-50 p-2 rounded border border-gray-100 line-clamp-2">
                                                "{notification.post.text?.substring(0, 100)}"
                                            </div>
                                        )}
                                    </div>
                                    {!notification.read && (
                                        <span className="w-2 h-2 bg-gray-800 rounded-full flex-shrink-0 mt-2"></span>
                                    )}
                                    <ArrowRight size={16} className="text-gray-400 flex-shrink-0 mt-2" />
                                </div>
                            </Link>
                        )
                    })}
                </div>
            )}
        </div>
    )
}
